:root { font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { display: grid; min-height: 100vh; margin: 0; place-items: center; padding: 20px; color: #ffffff; background: linear-gradient(135deg, #c2410c, #be185d); }
.countdown { width: min(100%, 720px); padding: clamp(24px, 6vw, 48px); border: 1px solid rgba(255,255,255,.2); border-radius: 24px; background: rgba(15, 23, 42, .28); backdrop-filter: blur(12px); text-align: center; }
h1 { margin: 0 0 28px; }
form { display: grid; gap: 9px; max-width: 500px; margin: 0 auto; text-align: left; }
label { margin-top: 8px; font-weight: 700; }
input, button { min-height: 46px; padding: 12px 14px; border: 0; border-radius: 10px; font: inherit; }
button { color: #9f1239; background: #ffffff; font-weight: 800; cursor: pointer; }
input:focus-visible, button:focus-visible { outline: 3px solid #fde68a; outline-offset: 3px; }
#form-error { min-height: 24px; margin: 0; color: #fef3c7; }
.units { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.units div { padding: 18px 8px; border-radius: 15px; background: rgba(255,255,255,.14); }
.units strong, .units span { display: block; }
.units strong { font-size: clamp(2rem, 9vw, 4rem); font-variant-numeric: tabular-nums; }
.units span { margin-top: 5px; color: #ffe4e6; }
#countdown-status { min-height: 28px; }
#reset { margin-top: 12px; background: rgba(255,255,255,.18); color: #ffffff; }
@media (max-width: 520px) { .units { grid-template-columns: repeat(2, 1fr); } }

const storageKey = 'countdown-v1';
const setup = document.querySelector('#setup');
const display = document.querySelector('#display');
const form = document.querySelector('#countdown-form');
const error = document.querySelector('#form-error');
const status = document.querySelector('#countdown-status');
const fields = ['days', 'hours', 'minutes', 'seconds'].map(id => document.querySelector('#' + id));
let timerId = null;

function showCountdown(data) {
  window.clearInterval(timerId);
  setup.hidden = true;
  display.hidden = false;
  document.querySelector('#display-title').textContent = data.name || '倒计时';
  const tick = () => {
    const remaining = data.target - Date.now();
    if (remaining <= 0) {
      fields.forEach(field => { field.textContent = '00'; });
      status.textContent = '时间到了！';
      window.clearInterval(timerId);
      return;
    }
    const values = [Math.floor(remaining / 86400000), Math.floor(remaining / 3600000) % 24, Math.floor(remaining / 60000) % 60, Math.floor(remaining / 1000) % 60];
    fields.forEach((field, index) => { field.textContent = String(values[index]).padStart(2, '0'); });
    status.textContent = '倒计时进行中';
  };
  tick();
  timerId = window.setInterval(tick, 1000);
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const target = new Date(document.querySelector('#target-time').value).getTime();
  if (!Number.isFinite(target) || target <= Date.now()) {
    error.textContent = '请选择一个未来的时间。';
    return;
  }
  const data = { name: document.querySelector('#event-name').value.trim(), target };
  localStorage.setItem(storageKey, JSON.stringify(data));
  error.textContent = '';
  showCountdown(data);
});

document.querySelector('#reset').addEventListener('click', () => {
  window.clearInterval(timerId);
  localStorage.removeItem(storageKey);
  form.reset();
  display.hidden = true;
  setup.hidden = false;
  document.querySelector('#event-name').focus();
});

try {
  const saved = JSON.parse(localStorage.getItem(storageKey));
  if (saved && Number.isFinite(saved.target)) showCountdown(saved);
} catch {
  localStorage.removeItem(storageKey);
}
